function backupExport(){const exportState=JSON.parse(JSON.stringify(state));exportState.audioClips=[];const blob=new Blob([JSON.stringify({app:'IELTS Boost Plan A Stage40-50',version:VERSION,exportedAt:new Date().toISOString(),audioNote:'Audio recordings are stored separately in IndexedDB. Download audio clips individually from the Privacy & Data tab.',state:exportState},null,2)],{type:'application/json'});downloadBlob(blob,'IELTS_Boost_PlanA_Progress_Backup.json');toast('Advanced Studio eski backup export. Unified Stage 55 backup tugmasidan foydalan.');}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
const AUDIO_DB_NAME='IELTSBoostPlanA_Audio_v1',AUDIO_STORE='clips';let audioDbPromise=null;
function openAudioDB(){if(!('indexedDB' in window))return Promise.reject(new Error('IndexedDB qo‘llab-quvvatlanmaydi.'));if(audioDbPromise)return audioDbPromise;audioDbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open(AUDIO_DB_NAME,1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(AUDIO_STORE))db.createObjectStore(AUDIO_STORE,{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||new Error('IndexedDB ochilmadi.'));});return audioDbPromise;}
async function putAudioClip(id,blob){const db=await openAudioDB();return new Promise((resolve,reject)=>{const tx=db.transaction(AUDIO_STORE,'readwrite');tx.objectStore(AUDIO_STORE).put({id,blob,updatedAt:new Date().toISOString()});tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error||new Error('Audio saqlanmadi.'));});}
async function getAudioClip(id){const db=await openAudioDB();return new Promise((resolve,reject)=>{const req=db.transaction(AUDIO_STORE,'readonly').objectStore(AUDIO_STORE).get(id);req.onsuccess=()=>resolve(req.result?.blob||null);req.onerror=()=>reject(req.error||new Error('Audio topilmadi.'));});}
async function deleteAudioClip(id){const db=await openAudioDB();return new Promise((resolve,reject)=>{const tx=db.transaction(AUDIO_STORE,'readwrite');tx.objectStore(AUDIO_STORE).delete(id);tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error||new Error('Audio o‘chirilmadi.'));});}
async function clearAudioDB(){if(!('indexedDB' in window))return;const db=await openAudioDB();return new Promise((resolve,reject)=>{const tx=db.transaction(AUDIO_STORE,'readwrite');tx.objectStore(AUDIO_STORE).clear();tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error||new Error('Audio bazasi tozalanmadi.'));});}
