 if(type==='reading'||type==='listening'){
  const raw=engine.scoreAnswerKey({keysText:$('#s59-answer-key')?.value||'',answersText:$('#s59-learner-answers')?.value||'',marksText:$('#s59-marks')?.value||'',unordered:$('#s59-unordered')?.checked});
  const keySource=$('#s59-key-source')?.value||'self';
  const sourceLabels={official:'Official sample / published key (user-selected)',publisher:'Publisher answer key (user-selected)',teacher:'Teacher-checked key (user-reported)',self:'Self-created key (not independently checked)'};
  record={score:raw.practiceIndex10,objective:true,accuracy:raw.accuracyPct/100,provenance:`Answer key · ${sourceLabels[keySource]}`,sourceLabel:sourceLabels[keySource],keySource,keySourceLabel:sourceLabels[keySource],rawResult:raw,correct:raw.correctQuestions,total:raw.questionCount,correctMarks:raw.correctMarks,totalMarks:raw.totalMarks,answerOrderIgnored:!!$('#s59-unordered')?.checked,form:$('#s59-test-form')?.value||'custom',format:'stage59-answer-key-v1'};
 }else{
  const criteria=collectStage59Rubric(type),responseText=$('#s59-response')?.value||'';
  const audioId=$('#s59-audio-id')?.value||'';
  const audioReviewed=$('#s59-audio-reviewed')?.checked===true;
  const result=engine.rubricScore({type,criteria,responseText,audioId,audioReviewed});
  if(type==='speaking'){
   const clip=(state.audioClips||[]).find(x=>x.id===audioId);
   if(!clip)throw Error('Selected audio record is not present in this device. Re-save the recording in Speaking Transcript.');
   const blob=await getAudioClip(audioId);
   if(!blob||!blob.size)throw Error('Audio metadata exists, but the real recording is missing from IndexedDB. Re-record or restore the audio first.');
   result.audioMetadata={id:clip.id,day:clip.day,part:clip.partLabel||clip.part,date:clip.date,durationMs:clip.durationMs,mime:clip.mime};
  }
  const taskPrompt=$('#s59-task-prompt')?.value?.trim()||'';
  if(!taskPrompt)throw Error('Paste the task prompt or speaking topic so the practice review has context.');
  record={score:result.score,objective:false,accuracy:null,provenance:result.sourceLabel,sourceLabel:result.sourceLabel,evidenceCoverage:result.evidenceCoverage,evidenceSources:result.evidenceSources,criteria:result.criteria,responseText:result.responseText,wordCount:result.wordCount,wordTarget:result.wordTarget,wordTargetReached:result.wordTargetReached,taskPrompt,audioId:result.audioId,audioReviewed:result.audioReviewed,scoreMeaning:result.scoreMeaning,format:'stage59-rubric-v1'};
 }
